-- composition of rule kernels L:extract_equijoin_predicate x L:simplify_expressions (datafusion), template exists
SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS ka WHERE EXISTS (SELECT 1 FROM (SELECT '_'::text AS c0, '2000-01-01'::date AS c1) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '_'::text AS c0, '2000-01-01'::date AS c1) AS kb) > 0 THEN (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS ka) ELSE 0 END
